import { computed, defineComponent, h, inject, onBeforeUnmount, onMounted, provide, ref, watch, Teleport, type ComputedRef, type InjectionKey, type PropType, type Ref } from 'vue';
import { commandStyleKeys, matchCommandItem } from '../lib/core';
import type { CommandFilterFn, CommandGroupDef, CommandItemDef } from '../lib/core';
import { usePortalContainer, type PortalContainer } from '../portal';
import styles from './command.module.scss';

interface CommandContextValue {
	search: string;
	setSearch: (value: string) => void;
	filter?: CommandFilterFn;
	loop: boolean;
	itemsRef: Ref<HTMLElement[]>;
	visibleCount: number;
	reportVisibility: (visible: boolean) => void;
}

type CommandContext = ComputedRef<CommandContextValue>;

const CommandContextKey: InjectionKey<CommandContext> = Symbol('tile-command');

function useCommandContext(): CommandContext {
	const context = inject(CommandContextKey);
	if (!context) {
		throw new Error('Command 子组件必须位于 <Command> 内部。');
	}
	return context;
}

function commandSearchIcon() {
	return h(
		'svg',
		{
			class: styles[commandStyleKeys.inputIcon],
			xmlns: 'http://www.w3.org/2000/svg',
			width: '16',
			height: '16',
			viewBox: '0 0 24 24',
			fill: 'none',
			stroke: 'currentColor',
			'stroke-width': '2',
			'stroke-linecap': 'round',
			'stroke-linejoin': 'round',
			'aria-hidden': 'true',
		},
		[h('circle', { cx: '11', cy: '11', r: '8' }), h('path', { d: 'm21 21-4.3-4.3' })],
	);
}

export const Command = defineComponent({
	name: 'Command',
	inheritAttrs: false,
	props: {
		items: { type: Array as PropType<CommandItemDef[]>, default: undefined },
		groups: { type: Array as PropType<CommandGroupDef[]>, default: undefined },
		filter: { type: Function as PropType<CommandFilterFn>, default: undefined },
		loop: { type: Boolean, default: true },
	},
	setup(props, { slots, attrs }) {
		const search = ref('');
		const itemsRef = ref<HTMLElement[]>([]);
		const visibleCount = ref(0);

		function setSearch(value: string) {
			search.value = value;
		}

		function reportVisibility(visible: boolean) {
			visibleCount.value += visible ? 1 : -1;
		}

		const context = computed<CommandContextValue>(() => ({
			search: search.value,
			setSearch,
			filter: props.filter,
			loop: props.loop,
			itemsRef,
			visibleCount: visibleCount.value,
			reportVisibility,
		}));

		provide(CommandContextKey, context);

		return () => {
			let content = slots.default?.();

			if (props.groups && props.groups.length > 0) {
				content = props.groups.map((group) =>
					h(CommandGroup, { key: group.value, heading: group.label }, () =>
						group.items.map((item) =>
							h(CommandItem, { key: item.value, value: item.value, keywords: item.keywords, disabled: item.disabled }, () => [
								item.label ?? item.value,
								item.shortcut ? h(CommandShortcut, () => [item.shortcut]) : null,
							]),
						),
					),
				);
			} else if (props.items && props.items.length > 0) {
				content = props.items.map((item) =>
					h(CommandItem, { key: item.value, value: item.value, keywords: item.keywords, disabled: item.disabled }, () => [
						item.label ?? item.value,
						item.shortcut ? h(CommandShortcut, () => [item.shortcut]) : null,
					]),
				);
			}

			return h('div', { ...attrs, class: [styles[commandStyleKeys.root], attrs.class] }, content);
		};
	},
});

export const CommandInput = defineComponent({
	name: 'CommandInput',
	inheritAttrs: false,
	props: {
		placeholder: { type: String, default: undefined },
	},
	setup(props, { attrs }) {
		const context = useCommandContext();

		return () =>
			h('div', { class: styles[commandStyleKeys.inputWrapper] }, [
				commandSearchIcon(),
				h('input', {
					...attrs,
					placeholder: props.placeholder,
					value: context.value.search,
					onInput: (event: Event) => {
						context.value.setSearch((event.target as HTMLInputElement).value);
					},
					class: [styles[commandStyleKeys.input], attrs.class],
				}),
			]);
	},
});

export const CommandList = defineComponent({
	name: 'CommandList',
	setup(_props, { slots, attrs }) {
		const context = useCommandContext();

		function handleKeyDown(event: KeyboardEvent) {
			const items = context.value.itemsRef.value.filter((item) => !item.hasAttribute('hidden') && item.getAttribute('data-disabled') !== 'true');
			if (items.length === 0) {
				return;
			}

			const currentIndex = items.findIndex((item) => item.getAttribute('data-selected') === 'true');

			const highlight = (next: number) => {
				items.forEach((item) => item.removeAttribute('data-selected'));
				items[next].setAttribute('data-selected', 'true');
				items[next].scrollIntoView({ block: 'nearest' });
			};

			const loop = context.value.loop;
			const nextFrom = (direction: 1 | -1): number => {
				if (currentIndex < 0) {
					return direction === 1 ? 0 : items.length - 1;
				}
				const next = currentIndex + direction;
				if (next < 0) {
					return loop ? items.length - 1 : 0;
				}
				if (next >= items.length) {
					return loop ? 0 : items.length - 1;
				}
				return next;
			};

			switch (event.key) {
				case 'ArrowDown':
					event.preventDefault();
					highlight(nextFrom(1));
					break;
				case 'ArrowUp':
					event.preventDefault();
					highlight(nextFrom(-1));
					break;
				case 'Enter':
					event.preventDefault();
					(currentIndex >= 0 ? items[currentIndex] : items[0]).click();
					break;
			}
		}

		return () => h('div', { ...attrs, class: [styles[commandStyleKeys.list], attrs.class], onKeydown: handleKeyDown }, slots.default?.());
	},
});

export const CommandEmpty = defineComponent({
	name: 'CommandEmpty',
	setup(_props, { slots, attrs }) {
		const context = useCommandContext();
		return () => {
			if (context.value.visibleCount > 0) {
				return null;
			}
			return h('div', { ...attrs, class: [styles[commandStyleKeys.empty], attrs.class] }, slots.default?.());
		};
	},
});

export const CommandGroup = defineComponent({
	name: 'CommandGroup',
	inheritAttrs: false,
	props: {
		heading: { type: String, default: undefined },
	},
	setup(props, { slots, attrs }) {
		return () =>
			h('div', { ...attrs, class: [styles[commandStyleKeys.group], attrs.class] }, [
				props.heading ? h('div', { class: styles[commandStyleKeys.groupLabel] }, [props.heading]) : null,
				h('div', { class: styles[commandStyleKeys.groupContent] }, slots.default?.()),
			]);
	},
});

export const CommandItem = defineComponent({
	name: 'CommandItem',
	inheritAttrs: false,
	props: {
		value: { type: String, required: true },
		keywords: { type: Array as PropType<string[]>, default: undefined },
		disabled: { type: Boolean, default: false },
	},
	emits: ['select'],
	setup(props, { emit, slots, attrs }) {
		const context = useCommandContext();
		const itemRef = ref<HTMLElement | null>(null);

		const matches = computed(() => {
			if (context.value.filter) {
				return context.value.filter(props.value, context.value.search, props.keywords);
			}
			return matchCommandItem({ value: props.value, keywords: props.keywords }, context.value.search);
		});

		onMounted(() => {
			if (itemRef.value) {
				context.value.itemsRef.value.push(itemRef.value);
			}
		});

		watch(
			matches,
			(visible, wasVisible) => {
				if (visible && !wasVisible) {
					context.value.reportVisibility(true);
				} else if (!visible && wasVisible) {
					context.value.reportVisibility(false);
				}
			},
			{ immediate: true },
		);

		onBeforeUnmount(() => {
			context.value.itemsRef.value = context.value.itemsRef.value.filter((item) => item !== itemRef.value);
			if (matches.value) {
				context.value.reportVisibility(false);
			}
		});

		function handleClick() {
			if (props.disabled) {
				return;
			}
			emit('select', props.value);
		}

		return () =>
			h(
				'div',
				{
					...attrs,
					ref: itemRef,
					tabindex: -1,
					hidden: !matches.value,
					'data-disabled': props.disabled,
					class: [styles[commandStyleKeys.item], attrs.class],
					onClick: handleClick,
				},
				slots.default?.(),
			);
	},
});

export const CommandSeparator = defineComponent({
	name: 'CommandSeparator',
	setup(_props, { attrs }) {
		return () => h('div', { ...attrs, class: [styles[commandStyleKeys.separator], attrs.class] });
	},
});

export const CommandShortcut = defineComponent({
	name: 'CommandShortcut',
	setup(_props, { slots, attrs }) {
		return () => h('span', { ...attrs, class: [styles[commandStyleKeys.shortcut], attrs.class] }, slots.default?.());
	},
});

export const CommandDialog = defineComponent({
	name: 'CommandDialog',
	props: {
		open: { type: Boolean, default: false },
		title: { type: String, default: 'Command Palette' },
		description: { type: String, default: 'Search for a command to run...' },
		showCloseButton: { type: Boolean, default: true },
		container: { type: Object as PropType<PortalContainer>, default: null },
	},
	emits: ['update:open'],
	setup(props, { emit, slots, attrs }) {
		const portalContainer = usePortalContainer(() => props.container);
		function handleOverlayClick() {
			emit('update:open', false);
		}

		function handleCloseClick() {
			emit('update:open', false);
		}

		function handleKeyDown(event: KeyboardEvent) {
			if (event.key === 'Escape') {
				emit('update:open', false);
			}
		}

		return () => {
			if (!props.open) {
				return null;
			}

			const dialogChildren = [
				h('h2', { class: styles[commandStyleKeys.dialogTitle] }, [props.title]),
				h('p', { class: styles[commandStyleKeys.dialogDescription] }, [props.description]),
				...(slots.default?.() ?? []),
			];

			if (props.showCloseButton) {
				dialogChildren.push(
					h(
						'button',
						{
							type: 'button',
							'aria-label': '关闭',
							class: styles[commandStyleKeys.dialogClose],
							onClick: handleCloseClick,
						},
						[
							h(
								'svg',
								{
									xmlns: 'http://www.w3.org/2000/svg',
									width: '16',
									height: '16',
									viewBox: '0 0 24 24',
									fill: 'none',
									stroke: 'currentColor',
									'stroke-width': '2',
									'stroke-linecap': 'round',
									'stroke-linejoin': 'round',
									'aria-hidden': 'true',
								},
								[h('path', { d: 'M18 6 6 18' }), h('path', { d: 'm6 6 12 12' })],
							),
						],
					),
				);
			}

			return h(Teleport, { to: portalContainer.value }, [
				h('div', { onKeydown: handleKeyDown }, [
					h('div', { class: styles[commandStyleKeys.dialogOverlay], onClick: handleOverlayClick }),
					h('div', { class: [styles[commandStyleKeys.dialogContent], attrs.class], role: 'dialog', 'aria-modal': 'true' }, dialogChildren),
				]),
			]);
		};
	},
});

export default Command;

@use '../../../styles/variables/colors' as *;

// 根容器
.root {
	display: flex;
	width: 100%;
	height: 100%;
	flex-direction: column;
	overflow: hidden;
	border-radius: var(--tile-command-radius, $radius);
	background-color: var(--tile-command-background, $popover);
	color: var(--tile-command-foreground, $popover-foreground);
}

// 输入框容器
.inputWrapper {
	display: flex;
	align-items: center;
	gap: var(--tile-command-input-gap, $spacing-2);
	border-bottom: 1px solid var(--tile-command-border, $border);
	padding: var(--tile-command-input-padding, 0 $spacing-3);
}

// 搜索输入框
.input {
	display: flex;
	width: 100%;
	height: var(--tile-command-input-height, 2.5rem);
	border: none;
	background: transparent;
	padding: $spacing-2 0;
	font-size: var(--tile-command-font-size, $text-sm);
	color: var(--tile-command-foreground, $foreground);
	outline: none;

	&::placeholder {
		color: var(--tile-command-subtle, $muted-foreground);
	}

	&[data-disabled='true'] {
		cursor: not-allowed;
		opacity: 0.5;
	}
}

// 输入框图标
.inputIcon {
	pointer-events: none;
	flex-shrink: 0;
	width: 1rem;
	height: 1rem;
	color: var(--tile-command-subtle, $muted-foreground);
	opacity: var(--tile-command-icon-opacity, 0.5);
}

// 列表容器
.list {
	max-height: 300px;
	overflow-x: hidden;
	overflow-y: auto;
	padding: var(--tile-command-list-padding, $spacing-1);
}

// 空状态
.empty {
	padding: var(--tile-command-empty-padding, $spacing-6);
	text-align: center;
	font-size: var(--tile-command-font-size, $text-sm);
	color: var(--tile-command-subtle, $muted-foreground);
}

// 分组容器
.group {
	overflow: hidden;
	padding: $spacing-1;
	color: var(--tile-command-foreground, $foreground);
}

// 分组标题
.groupLabel {
	padding: $spacing-1_5 $spacing-2;
	font-size: $text-xs;
	font-weight: var(--tile-command-label-font-weight, $font-medium);
	color: var(--tile-command-subtle, $muted-foreground);
}

// 分组内容
.groupContent {
	display: block;
}

// 命令项
.item {
	position: relative;
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: var(--tile-command-item-radius, $radius-sm);
	padding: var(--tile-command-item-padding, $spacing-1_5 $spacing-2);
	font-size: var(--tile-command-font-size, $text-sm);
	line-height: $leading-normal;
	color: var(--tile-command-foreground, $popover-foreground);
	outline: none;
	cursor: default;
	user-select: none;

	&[data-selected='true'] {
		background-color: var(--tile-command-highlight-background, $accent);
		color: var(--tile-command-highlight-foreground, $accent-foreground);
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}

	& > svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
		color: var(--tile-command-subtle, $muted-foreground);
	}
}

// 分隔线
.separator {
	margin: $spacing-1 (-$spacing-1);
	height: 1px;
	background-color: var(--tile-command-border, $border);
}

// 快捷键文本
.shortcut {
	margin-left: auto;
	font-size: $text-xs;
	letter-spacing: 0.1em;
	color: var(--tile-command-subtle, $muted-foreground);
}

// 对话框遮罩
.dialogOverlay {
	position: fixed;
	inset: 0;
	z-index: $z-modal;
	background-color: var(--tile-command-overlay, color-mix(in srgb, $overlay 80%, transparent));
}

// 对话框容器
.dialogContent {
	position: fixed;
	z-index: $z-modal;
	top: 50%;
	left: 50%;
	width: 100%;
	max-width: 32rem;
	transform: translate(-50%, -50%);
	overflow: hidden;
	border-radius: var(--tile-command-radius, $radius-lg);
	border: 1px solid var(--tile-command-border, $border);
	background-color: var(--tile-command-background, $popover);
	padding: 0;
	box-shadow: var(--tile-command-dialog-shadow, $shadow-lg);
	outline: none;
}

// 对话框标题
.dialogTitle {
	position: absolute;
	width: 1px;
	height: 1px;
	padding: 0;
	margin: -1px;
	overflow: hidden;
	clip: rect(0, 0, 0, 0);
	white-space: nowrap;
	border: 0;
}

// 对话框描述
.dialogDescription {
	position: absolute;
	width: 1px;
	height: 1px;
	padding: 0;
	margin: -1px;
	overflow: hidden;
	clip: rect(0, 0, 0, 0);
	white-space: nowrap;
	border: 0;
}

// 对话框关闭按钮
.dialogClose {
	position: absolute;
	top: $spacing-3;
	right: $spacing-3;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	padding: $spacing-1;
	border: none;
	border-radius: $radius;
	background-color: transparent;
	color: var(--tile-command-subtle, $muted-foreground);
	opacity: 0.7;
	cursor: pointer;
	transition: opacity $transition-fast;
	outline: none;

	&:hover {
		opacity: 1;
	}

	& > svg {
		pointer-events: none;
		width: 1rem;
		height: 1rem;
	}
}
